127	
128	/** Fast lookup by key. */
129	export const FEATURE_BY_KEY: Record<string, FeatureDef> = Object.fromEntries(
130	  FEATURE_CATALOG.map((f) => [f.key, f]),
131	);
132	
133	/** Three-state feature toggle (see migration 00208). */
134	export type FeatureVisibility = "off" | "everyone" | "admins";
135	
136	/** A raw registry row from v2_event_features (org-default or event-override). */
137	export interface FeatureRow {
138	  feature_key: string;
139	  event_id: string | null;
140	  visibility: FeatureVisibility;
141	  pinned: boolean;
142	  nav_order: number;
143	  label_override: string | null;
144	  public: boolean;
145	  availability: FeatureAvailability;
146	  available_from: string | null;
147	  available_until: string | null;
148	  open_notification_title?: string | null;
149	  open_notification_body?: string | null;
150	  open_notification_sent_at?: string | null;
151	}
152	
153	/** Where a resolved setting came from, for the config screen's inheritance hint. */
154	export type FeatureSource = "default" | "org" | "event";
155	
156	/** A catalog feature merged with its effective configuration for an event. */
157	export interface ResolvedFeature {
158	  def: FeatureDef;
159	  visibility: FeatureVisibility;
160	  pinned: boolean;
161	  navOrder: number;
162	  label: string; // label_override || def.label
163	  public: boolean;
164	  availability: FeatureAvailability;
165	  availableFrom: string | null;
166	  availableUntil: string | null;
167	  openNotificationTitle: string | null; // authored "it's open" notification (#218 generalized)
168	  openNotificationBody: string | null;
169	  source: FeatureSource; // strongest scope that set visibility
170	}
171	
172	function baseResolved(def: FeatureDef): ResolvedFeature {
173	  return {
174	    def,
175	    // alwaysOn (Profile) can't be turned off; a few (Chat/Photos/Music) default
176	    // to everyone but stay toggleable; everything else is off (opt-in).
177	    visibility: def.alwaysOn || def.defaultEnabled ? "everyone" : "off",
178	    pinned: false,
179	    navOrder: 0,
180	    label: def.label,
181	    public: !!def.defaultPublic,
182	    availability: "always",
183	    availableFrom: null,
184	    availableUntil: null,
185	    openNotificationTitle: null,
186	    openNotificationBody: null,
187	    source: "default",
188	  };
189	}
190	
191	function applyRow(acc: ResolvedFeature, row: FeatureRow, source: FeatureSource): ResolvedFeature {
192	  return {
193	    ...acc,
194	    visibility: acc.def.alwaysOn ? "everyone" : row.visibility,
195	    pinned: row.pinned,
196	    navOrder: row.nav_order,
197	    label: row.label_override?.trim() || acc.def.label,
198	    public: row.public,
199	    availability: row.availability,
200	    availableFrom: row.available_from,
201	    availableUntil: row.available_until,
202	    openNotificationTitle: row.open_notification_title ?? acc.openNotificationTitle,
203	    openNotificationBody: row.open_notification_body ?? acc.openNotificationBody,
204	    source,
205	  };
206	}
207	
208	/** Is a feature visible to this viewer? ('admins' requires org admin/owner.) */
209	export function isVisibleTo(f: ResolvedFeature, viewerIsAdmin: boolean): boolean {
210	  if (f.visibility === "everyone") return true;
211	  if (f.visibility === "admins") return viewerIsAdmin;
212	  return false;
213	}
214	
215	/**
216	 * Merge catalog defaults < org defaults (event_id null) < event overrides for a
217	 * given event, returning every catalog feature in catalog order.
218	 */
219	export function resolveFeatures(rows: FeatureRow[], eventId: string): ResolvedFeature[] {
220	  const orgRows = new Map(rows.filter((r) => r.event_id === null).map((r) => [r.feature_key, r]));
221	  const eventRows = new Map(rows.filter((r) => r.event_id === eventId).map((r) => [r.feature_key, r]));
222	
223	  return FEATURE_CATALOG.map((def) => {
224	    let acc = baseResolved(def);
225	    const org = orgRows.get(def.key);
226	    if (org) acc = applyRow(acc, org, "org");
227	    const ev = eventRows.get(def.key);
228	    if (ev) acc = applyRow(acc, ev, "event");
229	    return acc;
230	  });
231	}
232	
233	/** Is a visible feature currently within its availability window? */
234	export function isFeatureActive(
235	  f: ResolvedFeature,
236	  viewerIsAdmin: boolean,
237	  now = new Date(),
238	): boolean {
239	  if (!isVisibleTo(f, viewerIsAdmin)) return false;
240	  if (f.availability !== "window") return true;
241	  const t = now.getTime();
242	  if (f.availableFrom && t < new Date(f.availableFrom).getTime()) return false;
243	  if (f.availableUntil && t > new Date(f.availableUntil).getTime()) return false;
244	  return true;
245	}
246	
247	/** Has a visible feature reached its open time? (past available_from; maybe past close).
248	 *  Used for "show it, but read-only once the window has ended." */
249	export function featureHasOpened(f: ResolvedFeature, viewerIsAdmin: boolean, now = new Date()): boolean {
250	  if (!isVisibleTo(f, viewerIsAdmin)) return false;
251	  if (f.availability !== "window") return true;
252	  if (f.availableFrom && now.getTime() < new Date(f.availableFrom).getTime()) return false;
253	  return true;
254	}
255	
256	/** The bottom-bar pins: visible, non-topbar, `pinned`, ordered, capped at 3. */
257	export function pinnedFeatures(
258	  resolved: ResolvedFeature[],
259	  viewerIsAdmin: boolean,
260	  max = 3,
261	): ResolvedFeature[] {
262	  return resolved
263	    .filter((f) => isVisibleTo(f, viewerIsAdmin) && f.pinned && !f.def.topbar)
264	    .sort((a, b) => a.navOrder - b.navOrder || a.def.label.localeCompare(b.def.label))
265	    .slice(0, max);
266	}
267	
268	/** Visible, non-topbar features grouped for the "Everything" launcher. */
269	export function launcherBuckets(
270	  resolved: ResolvedFeature[],
271	  viewerIsAdmin: boolean,
272	): { bucket: BucketDef; features: ResolvedFeature[] }[] {
273	  return FEATURE_BUCKETS.map((bucket) => ({
274	    bucket,
275	    features: resolved.filter(
276	      (f) => isVisibleTo(f, viewerIsAdmin) && !f.def.topbar && f.def.bucket === bucket.key,
277	    ),
278	  })).filter((g) => g.features.length > 0);
279	}
280	
281	/**
282	 * Is a specific feature visible to this viewer? Used to gate the top-bar utility
283	 * buttons (Chat/Photos/Music). Defaults to visible if the feature has no row yet
284	 * (so the app doesn't hide things before the registry is configured).
285	 */
286	export function isFeatureVisible(
287	  resolved: ResolvedFeature[],
288	  key: string,
289	  viewerIsAdmin: boolean,
290	): boolean {
291	  const f = resolved.find((r) => r.def.key === key);
292	  return f ? isVisibleTo(f, viewerIsAdmin) : true;
293	}
294	
295	/** Is Music visible to this viewer? (topbar utility with a group toggle.) */
296	export function isMusicEnabled(resolved: ResolvedFeature[], viewerIsAdmin: boolean): boolean {
297	  return isFeatureVisible(resolved, "music", viewerIsAdmin);
298	}
299	
300	/** Max number of bottom-bar pins (Home + these + Everything + Admin). */
301	export const MAX_PINNED = 3;
302	
303	/* ── Nav building (bottom bar + "Everything" launcher) ─────────────────────── */
304	
305	/**
306	 * Destination path for a feature's landing page, or null if it isn't browsable
307	 * yet. Only `route`/`external` features route here (tier-1 drawers open in place).
308	 * As each feature ports, add its route here and flip its catalog `status`.
309	 */
310	const FEATURE_ROUTES: Record<string, (slug: string) => string> = {
311	  articles: (slug) => `/new/${slug}/articles`,
312	  courses: (slug) => `/new/${slug}/courses`,
313	  loozers: (slug) => `/new/${slug}/loozers`,
314	  schedule: (slug) => `/new/${slug}/schedule`,
315	  options: (slug) => `/new/${slug}/options`,
316	  balance: (slug) => `/new/${slug}/balance`,
317	  pickem: (slug) => `/new/${slug}/pickem`,
318	};
319	
320	export function featureHref(slug: string, def: FeatureDef): string | null {
321	  const build = FEATURE_ROUTES[def.key];
322	  return build ? build(slug) : null;
323	}
324	
325	function fmtShortDate(iso: string): string {
326	  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric" });
327	}
328	
329	/** A resolved feature flattened for the shell (bottom bar + launcher). */
330	export interface NavFeature {
331	  key: string;
332	  label: string;
333	  icon: string;
334	  bucket: FeatureBucket;
335	  blurb: string;
336	  href: string | null;
337	  /** Navigable right now (has a destination and within any availability window). */
338	  active: boolean;
339	  /** Why it isn't navigable ("Coming soon" / "Opens Mar 3" / "Closed"), or null. */
340	  lockReason: string | null;
341	  /** Shown only to admins (visibility='admins') — badge it so they know. */
342	  adminOnly: boolean;
343	}
344	
345	function lockReasonFor(f: ResolvedFeature, href: string | null, now: Date): string | null {
346	  if (f.availability === "window") {
347	    if (f.availableFrom && now.getTime() < new Date(f.availableFrom).getTime()) {
348	      return `Opens ${fmtShortDate(f.availableFrom)}`;
349	    }
350	    if (f.availableUntil && now.getTime() > new Date(f.availableUntil).getTime()) {
351	      return "Closed";
352	    }
353	  }
354	  return href ? null : "Coming soon";
355	}
356	
357	export function toNavFeature(slug: string, f: ResolvedFeature, now = new Date()): NavFeature {
358	  const href = featureHref(slug, f.def);
359	  const lockReason = lockReasonFor(f, href, now);
360	  return {
361	    key: f.def.key,
362	    label: f.label,
363	    icon: f.def.icon,
364	    bucket: f.def.bucket,
365	    blurb: f.def.blurb,
366	    href,
367	    active: lockReason === null,
368	    lockReason,
369	    adminOnly: f.visibility === "admins",
370	  };
371	}
372	
373	export interface LauncherGroup {
374	  bucketKey: FeatureBucket;
375	  bucketLabel: string;
376	  features: NavFeature[];
377	}
378	
379	/**
380	 * The complete shell nav for an event: the (≤3) bottom-bar pins and the
381	 * "Everything" launcher grouped by bucket. Availability windows are resolved
382	 * against `now` on the server, so the client renders static state (no Date in
383	 * render). Falls back to empty arrays when nothing is enabled.
384	 */
385	export function buildEventNav(
386	  slug: string,
387	  resolved: ResolvedFeature[],
388	  viewerIsAdmin: boolean,
389	  now = new Date(),
390	): { pinned: NavFeature[]; launcher: LauncherGroup[] } {
391	  const pinned = pinnedFeatures(resolved, viewerIsAdmin).map((f) => toNavFeature(slug, f, now));
392	  const launcher = launcherBuckets(resolved, viewerIsAdmin).map((g) => ({
393	    bucketKey: g.bucket.key,
394	    bucketLabel: g.bucket.label,
395	    features: g.features.map((f) => toNavFeature(slug, f, now)),
396	  }));
397	  return { pinned, launcher };
398	}
