1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import Modal from "@/app/new/_components/Modal";
5	import styles from "@/app/new/new.module.css";
6	
7	export interface ScoreHole { hole_number: number; par: number; handicap_index: number }
8	export interface ScoreTeam { id: string; name: string | null; team_handicap: number | null; members: string[] }
9	interface ScoreRow { team_id: string; hole_number: number; strokes: number }
10	interface ObsRow { user_id: string; hole_number: number; metric: string; value: number }
11	interface PlayerObs { on_green: boolean; holed_out: boolean }
12	
13	/**
14	 * Scramble scoring — review-first (#209). A list of groups with their round
15	 * summary; tapping a group expands an inline scorecard. Tapping a hole opens a
16	 * floating editor (team score stepper + each player's Green / Putt toggle) with
17	 * prev/next arrows. Optimistic: one hole saved per PUT in the background.
18	 */
19	export default function ScoringManager({
20	  orgId,
21	  eventId,
22	  contestId,
23	  holes,
24	  teams,
25	  initialScores,
26	  initialObs,
27	  names,
28	}: {
29	  orgId: string;
30	  eventId: string;
31	  contestId: string;
32	  holes: ScoreHole[];
33	  teams: ScoreTeam[];
34	  initialScores: ScoreRow[];
35	  initialObs: ObsRow[];
36	  names: Record<string, string>;
37	}) {
38	  const [expanded, setExpanded] = useState<Set<string>>(new Set());
39	  const [scores, setScores] = useState<Record<string, Record<number, number>>>(() => {
40	    const m: Record<string, Record<number, number>> = {};
41	    for (const s of initialScores) (m[s.team_id] ||= {})[s.hole_number] = s.strokes;
42	    return m;
43	  });
44	  const [obs, setObs] = useState<Record<string, PlayerObs>>(() => {
45	    const m: Record<string, PlayerObs> = {};
46	    for (const o of initialObs) {
47	      const k = `${o.user_id}|${o.hole_number}`;
48	      const cur = m[k] || { on_green: false, holed_out: false };
49	      if (o.metric === "on_green") cur.on_green = o.value === 1;
50	      if (o.metric === "holed_out") cur.holed_out = o.value === 1;
51	      m[k] = cur;
52	    }
53	    return m;
54	  });
55	  const [editTeamId, setEditTeamId] = useState<string | null>(null);
56	  const [editHole, setEditHole] = useState<number | null>(null);
57	  const [wScore, setWScore] = useState<number | "">("");
58	  const [wPlayers, setWPlayers] = useState<Record<string, PlayerObs>>({});
59	
60	  const lowestHcp = teams.length ? Math.min(...teams.map((t) => t.team_handicap ?? 0)) : 0;
61	  const holeByNum = useMemo(() => new Map(holes.map((h) => [h.hole_number, h])), [holes]);
62	  const holeNums = useMemo(() => holes.map((h) => h.hole_number).sort((a, b) => a - b), [holes]);
63	  const editTeam = teams.find((t) => t.id === editTeamId) || null;
64	
