175	export async function autoEnrollFromRoster(
176	  admin: SupabaseClient,
177	  contestId: string,
178	  eventId: string,
179	): Promise<number> {
180	  const { data: roster } = await admin
181	    .from("v2_event_participants")
182	    .select("user_id")
183	    .eq("event_id", eventId)
184	    .eq("on_roster", true);
185	  const rosterIds = (roster || []).map((r) => r.user_id as string);
186	  if (rosterIds.length === 0) return 0;
187	
188	  const { data: existing } = await admin
189	    .from("v2_contest_participants")
190	    .select("user_id")
191	    .eq("contest_id", contestId);
192	  const have = new Set((existing || []).map((r) => r.user_id as string));
193	
194	  const toAdd = rosterIds.filter((id) => !have.has(id)).map((user_id) => ({ contest_id: contestId, user_id }));
195	  if (toAdd.length === 0) return 0;
196	  const { error } = await admin.from("v2_contest_participants").insert(toAdd);
197	  if (error) return 0;
198	  return toAdd.length;
199	}
