3	/**
4	 * Managed auto-membership chat channels (#192 follow-up, v1 parity).
5	 *
6	 *   all_members — one per org; always holds every active, non-archived member.
7	 *   event       — one per event; holds everyone opted into the event (on_roster).
8	 *
9	 * These helpers keep v2_chat_room_members in sync from the app layer (wired into
10	 * org-join, member archive/restore, RSVP, and event creation). Every caller
11	 * treats them as best-effort: a sync failure must never block the primary action.
12	 * All writes go through the service-role client.
13	 */
14	
15	/** Find-or-create the org's all-members channel; returns its id. */
16	export async function ensureAllMembersRoom(admin: SupabaseClient, orgId: string): Promise<string> {
17	  const { data: existing } = await admin
18	    .from("v2_chat_rooms")
19	    .select("id")
20	    .eq("org_id", orgId)
21	    .eq("room_kind", "all_members")
22	    .maybeSingle();
23	  if (existing) return existing.id as string;
24	
25	  const { data: org } = await admin
26	    .from("v2_organizations")
27	    .select("member_noun_plural")
28	    .eq("id", orgId)
29	    .maybeSingle();
30	  const noun = (org?.member_noun_plural as string | null)?.trim() || "Members";
31	
32	  const { data: room, error } = await admin
33	    .from("v2_chat_rooms")
34	    .insert({ org_id: orgId, type: "group", name: `All ${noun}`, room_kind: "all_members" })
35	    .select("id")
36	    .single();
37	  if (error) throw error;
38	  return room.id as string;
39	}
40	
41	/** Add an active member to the all-members channel (idempotent). */
42	export async function addToAllMembers(admin: SupabaseClient, orgId: string, userId: string): Promise<void> {
43	  const roomId = await ensureAllMembersRoom(admin, orgId);
44	  await admin
45	    .from("v2_chat_room_members")
46	    .upsert({ room_id: roomId, user_id: userId, role: "member" }, { onConflict: "room_id,user_id", ignoreDuplicates: true });
47	}
48	
49	/**
50	 * Remove a user from every managed channel in an org (all_members + all event
51	 * channels). Used when a member is archived or removed. Their messages stay.
52	 */
53	export async function removeFromManagedChannels(admin: SupabaseClient, orgId: string, userId: string): Promise<void> {
54	  const { data: rooms } = await admin
55	    .from("v2_chat_rooms")
56	    .select("id")
57	    .eq("org_id", orgId)
58	    .in("room_kind", ["all_members", "event"]);
59	  const ids = (rooms || []).map((r) => r.id as string);
60	  if (ids.length === 0) return;
61	  await admin.from("v2_chat_room_members").delete().in("room_id", ids).eq("user_id", userId);
62	}
63	
64	/** Find-or-create an event's channel; returns its id. */
65	export async function ensureEventRoom(
66	  admin: SupabaseClient,
67	  orgId: string,
68	  eventId: string,
69	  name: string,
70	): Promise<string> {
71	  const { data: existing } = await admin
72	    .from("v2_chat_rooms")
73	    .select("id")
74	    .eq("event_id", eventId)
75	    .eq("room_kind", "event")
76	    .maybeSingle();
77	  if (existing) return existing.id as string;
78	
79	  const { data: room, error } = await admin
80	    .from("v2_chat_rooms")
81	    .insert({ org_id: orgId, event_id: eventId, type: "group", name, room_kind: "event" })
82	    .select("id")
83	    .single();
84	  if (error) throw error;
85	  return room.id as string;
86	}
87	
88	/**
89	 * Sync one member's event-channel membership to their opt-in state. `optedIn`
90	 * (on_roster / likelihood===99) adds them with full history; opting out removes
91	 * the membership so the room leaves their list — messages persist. No-op if the
92	 * event has no channel (e.g. an event that predates the feature).
93	 */
94	export async function syncEventChannelMembership(
95	  admin: SupabaseClient,
96	  eventId: string,
97	  userId: string,
98	  optedIn: boolean,
99	): Promise<void> {
100	  const { data: room } = await admin
101	    .from("v2_chat_rooms")
102	    .select("id")
103	    .eq("event_id", eventId)
104	    .eq("room_kind", "event")
105	    .maybeSingle();
106	  if (!room) return;
107	
108	  if (optedIn) {
109	    await admin
110	      .from("v2_chat_room_members")
111	      .upsert({ room_id: room.id, user_id: userId, role: "member" }, { onConflict: "room_id,user_id", ignoreDuplicates: true });
112	  } else {
113	    await admin.from("v2_chat_room_members").delete().eq("room_id", room.id).eq("user_id", userId);
114	  }
115	}
