3	/**
4	 * New-group onboarding checklist (#196). Computes which setup steps a freshly
5	 * created group has finished, entirely from real data — no per-step flags to
6	 * keep in sync. The "Get your group ready" card on the group home renders these
7	 * for admins until every step is done or the card is dismissed.
8	 *
9	 * Step completion signals (all derived, never manually toggled):
10	 *   1 Name       — always done (an org can't exist without a name)
11	 *   2 Logo & colors — a logo has been uploaded (logo_url set)
12	 *   3 First event   — the org has at least one event (any status)
13	 *   4 Features      — the admin has saved a feature config (an org-default row exists)
14	 *   5 Invite members— at least one invite sent OR a second member has joined
15	 */
16	
17	export interface OnboardingStep {
18	  key: "name" | "brand" | "event" | "features" | "members";
19	  label: string;
20	  desc: string;
21	  href: string | null; // deep-link to the admin surface; null once done
22	  done: boolean;
23	}
24	
25	export interface OnboardingState {
26	  steps: OnboardingStep[];
27	  completed: number;
28	  total: number;
29	  allDone: boolean;
30	  dismissed: boolean;
31	  /** Show the card only when the viewer is an admin, it isn't dismissed, and work remains. */
32	  show: boolean;
33	}
34	
35	export async function getOnboardingState(
36	  supabase: SupabaseClient,
37	  org: { id: string; slug: string; logo_url: string | null },
38	  isAdmin: boolean,
39	): Promise<OnboardingState> {
40	  const base = `/new/${org.slug}/admin`;
41	
42	  const [orgRes, eventsRes, featuresRes, invitesRes, membersRes] = await Promise.all([
43	    supabase.from("v2_organizations").select("onboarding_dismissed_at").eq("id", org.id).maybeSingle(),
44	    supabase.from("v2_events").select("id", { count: "exact", head: true }).eq("org_id", org.id),
45	    supabase
46	      .from("v2_event_features")
47	      .select("feature_key", { count: "exact", head: true })
48	      .eq("org_id", org.id)
49	      .is("event_id", null),
50	    supabase.from("v2_invites").select("id", { count: "exact", head: true }).eq("org_id", org.id),
51	    supabase
52	      .from("v2_memberships")
53	      .select("user_id", { count: "exact", head: true })
54	      .eq("org_id", org.id)
55	      .eq("status", "active"),
56	  ]);
57	
58	  const hasLogo = !!org.logo_url;
59	  const hasEvent = (eventsRes.count ?? 0) > 0;
60	  const hasFeatures = (featuresRes.count ?? 0) > 0;
61	  const hasInvites = (invitesRes.count ?? 0) > 0;
62	  const hasOtherMembers = (membersRes.count ?? 0) > 1;
63	  const dismissed = !!(orgRes.data as { onboarding_dismissed_at: string | null } | null)?.onboarding_dismissed_at;
64	
65	  const steps: OnboardingStep[] = [
66	    {
