1	import type { SupabaseClient } from "@supabase/supabase-js";
2	import { sendV2Notifications } from "./notifications";
3	import { logActivity } from "./activity";
4	
5	/**
6	 * Announcement audience + delivery helpers, shared by the /api/v2/announcements
7	 * routes and the v2-announcements cron so "send now" and scheduled sends resolve
8	 * recipients and dispatch notifications identically.
9	 */
10	
11	export type AnnouncementAudience = "everyone" | "event" | "custom";
12	
13	export interface AnnouncementRow {
14	  id: string;
15	  org_id: string;
16	  title: string;
17	  body: string | null;
18	  audience_type: AnnouncementAudience;
19	  audience_user_ids: string[] | null;
20	  event_id: string | null;
21	  created_by?: string | null;
22	  send_as_system?: boolean;
23	}
24	
25	/**
26	 * Resolve the set of member user IDs an announcement targets.
27	 *   everyone → all active org members
28	 *   event    → event participants who haven't RSVP'd 'not_going'
29	 *   custom   → the stored audience_user_ids (deduped)
30	 */
31	export async function resolveAnnouncementAudience(
32	  admin: SupabaseClient,
33	  a: Pick<AnnouncementRow, "org_id" | "audience_type" | "audience_user_ids" | "event_id">,
34	): Promise<string[]> {
35	  if (a.audience_type === "custom") {
36	    return [...new Set((a.audience_user_ids || []).filter(Boolean))];
37	  }
38	  if (a.audience_type === "event") {
39	    if (!a.event_id) return [];
40	    const { data } = await admin
41	      .from("v2_event_participants")
42	      .select("user_id, status")
43	      .eq("event_id", a.event_id)
44	      .neq("status", "not_going");
45	    return [...new Set((data || []).map((p) => p.user_id).filter(Boolean))];
46	  }
47	  // everyone
48	  const { data } = await admin
49	    .from("v2_memberships")
50	    .select("user_id")
51	    .eq("org_id", a.org_id)
52	    .eq("status", "active")
53	    .is("archived_at", null);
54	  return [...new Set((data || []).map((m) => m.user_id).filter(Boolean))];
55	}
56	
57	/**
58	 * Resolve the audience and deliver an announcement as notifications + push.
59	 * Returns how many members were notified (for the recipient_count snapshot).
60	 * Announcements are important broadcasts, so there's no per-type opt-out — they
61	 * always log in-app; push still honors each member's push_master toggle (handled
62	 * inside sendV2Notifications).
63	 */
64	export async function deliverAnnouncement(
65	  admin: SupabaseClient,
66	  a: AnnouncementRow,
67	  slug: string | null,
68	): Promise<number> {
69	  const userIds = await resolveAnnouncementAudience(admin, a);
70	  const link = slug ? `/new/${slug}/announcements?a=${a.id}` : null;
71	  if (userIds.length) {
72	    await sendV2Notifications(admin, userIds, {
73	      orgId: a.org_id,
74	      type: "announcement",
75	      title: a.title,
76	      body: a.body || undefined,
77	      data: {
78	        announcementId: a.id,
79	        ...(link ? { url: link } : {}),
80	      },
81	    });
82	  }
83	
84	  // Surface org-wide announcements in the home activity feed. Targeted ones
85	  // (event/custom) are deliberately NOT logged — the feed is org-wide, so posting
86	  // a subset-audience announcement there would leak it to non-recipients.
87	  if (a.audience_type === "everyone") {
88	    // First line of the body as a preview under the headline.
89	    const firstLine = (a.body || "")
90	      .split("\n")
91	      .map((l) => l.trim())
92	      .find((l) => l.length > 0);
93	    // actor_id always records the real sender (provenance). When sent "as the
94	    // system", metadata.system tells the feed to PRESENT the org's system
95	    // identity (name + avatar) instead of the sender.
96	    await logActivity(admin, {
97	      orgId: a.org_id,
98	      kind: "announcement",
99	      actorId: a.created_by ?? null,
100	      // Just show the announcement itself — no "posted an announcement" label.
101	      title: a.title,
102	      subtitle: firstLine ? (firstLine.length > 140 ? `${firstLine.slice(0, 140)}…` : firstLine) : null,
103	      link,
104	      refId: a.id,
105	      metadata: { system: !!a.send_as_system },
106	    });
107	  }
108	
109	  return userIds.length;
110	}
