19	import { pickName, type NameMode } from "./profile";
20	
21	/** How far back the feed reaches; everything from here forward is included. */
22	const PAST_WINDOW_DAYS = 30;
23	/** How far ahead derived birthdays project (authored items have no forward cap). */
24	const BIRTHDAY_HORIZON_DAYS = 400;
25	
26	interface AuthoredRow {
27	  id: string;
28	  event_id: string | null;
29	  title: string;
30	  description: string | null;
31	  location: string | null;
32	  day: string;
33	  end_day: string | null;
34	  start_time: string | null;
