76	
77	  const entries: CalendarEntry[] = [];
78	
79	  // ── Authored items: group-level (event_id NULL) + items of active events ─────
80	  // A single query with an OR so it's one round-trip.
81	  const eventClause = activeIds.length ? `event_id.in.(${activeIds.join(",")})` : null;
82	  const orFilter = eventClause ? `event_id.is.null,${eventClause}` : "event_id.is.null";
83	  const { data: itemRows } = await admin
84	    .from("v2_schedule_items")
85	    .select(
86	      "id, event_id, title, description, location, day, end_day, start_time, end_time, all_day, sort_order, kind, activity_type, activity_id",
87	    )
88	    .eq("org_id", orgId)
89	    .or(orFilter)
90	    .gte("day", windowStart)
91	    .order("day");
92	
93	  for (const it of (itemRows || []) as AuthoredRow[]) {
94	    const ev = it.event_id ? eventById.get(it.event_id) : null;
95	    entries.push({
96	      id: `item:${it.id}`,
97	      source: it.activity_id ? "activity" : it.event_id ? "event" : "group",
98	      title: it.title,
99	      description: it.description,
100	      location: it.location,
101	      day: it.day,
102	      end_day: it.end_day,
103	      start_time: it.start_time,
104	      end_time: it.end_time,
105	      all_day: it.all_day,
106	      sort_order: it.sort_order,
107	      context: ev ? ev.name : null,
108	      href: null,
109	    });
110	  }
111	
112	  // ── Derived: one all-day span per active event ───────────────────────────────
113	  for (const ev of events) {
114	    if (!ev.start_date) continue;
115	    const end = ev.end_date && ev.end_date !== ev.start_date ? ev.end_date : null;
116	    // Skip spans wholly before the window.
117	    if ((end || ev.start_date) < windowStart) continue;
118	    entries.push({
119	      id: `event:${ev.id}`,
120	      source: "event-span",
121	      title: ev.name,
122	      description: null,
123	      location: null,
124	      day: ev.start_date,
125	      end_day: end,
126	      start_time: null,
127	      end_time: null,
128	      all_day: true,
129	      sort_order: -100, // sort an event banner above the day's timed items
130	      context: null,
131	      href: null,
132	    });
133	  }
134	
135	  // ── Derived: birthdays from member profiles (opt-out per org) ────────────────
136	  if (includeBirthdays) {
137	    const { data: members } = await admin
138	      .from("v2_memberships")
139	      .select("user_id, v2_profiles!inner(id, display_name, first_name, last_name, birthdate)")
140	      .eq("org_id", orgId)
141	      .eq("status", "active");
142	    const horizonEnd = addDaysYMD(today, BIRTHDAY_HORIZON_DAYS);
143	    for (const m of members || []) {
