166	          end_day: null,
167	          start_time: null,
168	          end_time: null,
169	          all_day: true,
170	          sort_order: -50, // above timed items, below the event banner
171	          context: null,
172	          href: `/new/${slug}/loozers/${p.id}`,
173	        });
174	      }
175	    }
176	  }
