26	function dateRange(start: string | null, end: string | null): string | null {
27	  if (!start) return null;
28	  const fmt = (iso: string) =>
29	    new Date(iso + "T00:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric" });
30	  const startYear = new Date(start + "T00:00:00").getFullYear();
31	  if (end && end !== start) {
32	    const endYear = new Date(end + "T00:00:00").getFullYear();
33	    return endYear !== startYear
34	      ? `${fmt(start)}, ${startYear} – ${fmt(end)}, ${endYear}`
35	      : `${fmt(start)} – ${fmt(end)}, ${startYear}`;
36	  }
37	  return `${fmt(start)}, ${startYear}`;
38	}
