1	/**
2	 * Skins scoring (#183). Lowest score on a hole wins that hole's skin. With
3	 * carryover on, a tied hole rolls its skin to the next hole so a later winner can
4	 * sweep several at once; with it off (the default), a tied hole's skin is simply
5	 * dead and every hole is worth exactly one. Pure and derived entirely from per-hole
6	 * scores — call it live from the scorer.
7	 *
8	 * Live semantics: holes are resolved in order; the first hole not yet scored by
9	 * every participant stops resolution (later holes stay pending), and any unresolved
10	 * skins (carryover only) show as "carrying".
11	 */
12	
13	export interface SkinsResult {
14	  /** Per resolved hole: who won it (round_player_id) or null when it carried. */
15	  perHole: { hole_number: number; winner: string | null; skins: number }[];
16	  /** round_player_id → skins won. */
17	  wonBy: Record<string, number>;
18	  /** Skins currently carried (unresolved ties waiting on the next decisive hole). */
19	  carrying: number;
20	  /** How many holes have been fully scored + resolved. */
21	  resolved: number;
22	}
23	
24	/**
25	 * @param holeNumbers  the round's holes in play order
26	 * @param scores       round_player_id → { hole_number → (net or gross) strokes }
27	 * @param participantIds  round_player_ids in the game
28	 */
29	export function computeSkins(
30	  holeNumbers: number[],
31	  scores: Record<string, Record<number, number>>,
32	  participantIds: string[],
33	  carryOver = false,
34	): SkinsResult {
35	  const perHole: SkinsResult["perHole"] = [];
36	  const wonBy: Record<string, number> = {};
37	  for (const id of participantIds) wonBy[id] = 0;
38	  let carry = 0;
39	  let resolved = 0;
40	
41	  for (const h of holeNumbers) {
42	    // Every participant must have a score for this hole to resolve it.
43	    const entries = participantIds.map((id) => ({ id, s: scores[id]?.[h] }));
44	    if (entries.some((e) => e.s == null)) break;
45	
46	    const low = Math.min(...entries.map((e) => e.s as number));
47	    const winners = entries.filter((e) => e.s === low);
48	    const atStake = carryOver ? carry + 1 : 1;
49	    if (winners.length === 1) {
50	      const w = winners[0].id;
51	      wonBy[w] = (wonBy[w] ?? 0) + atStake;
