53	      carry = 0;
54	    } else {
55	      // Tie: with carryover the pot rolls forward; otherwise the skin is dead.
56	      perHole.push({ hole_number: h, winner: null, skins: atStake });
57	      carry = carryOver ? atStake : 0;
