3	/**
4	 * Scramble skins (#209). Per hole, the team with the UNIQUE low score wins the
5	 * skin; ties push (carry to the next decided hole when carryover is on, else the
6	 * skin is dead). Net uses each team's adjusted handicap (lowest team plays 0) and
7	 * the hole's stroke index; gross uses raw team scores. Only teams that have
8	 * recorded a score count as "in the field", and a hole is decided once all of them
9	 * have scored it (so partial rounds compute live).
10	 */
11	
12	export interface SkinsRow { team_id: string; skins: number }
13	export interface SkinsResult { rows: SkinsRow[]; decided: number; pending: number }
14	
15	export function computeSkins(
16	  teams: { id: string; team_handicap: number | null }[],
17	  scoresByTeam: Record<string, Record<number, number>>,
18	  holes: { hole_number: number; handicap_index: number }[],
19	  opts: { net: boolean; carryover: boolean },
20	): SkinsResult {
21	  const active = teams.filter((t) => scoresByTeam[t.id] && Object.keys(scoresByTeam[t.id]).length > 0);
22	  if (active.length < 2) return { rows: active.map((t) => ({ team_id: t.id, skins: 0 })), decided: 0, pending: holes.length };
23	
24	  const lowest = Math.min(...active.map((t) => t.team_handicap ?? 0));
25	  const adjOf = (t: { team_handicap: number | null }) => Math.max(0, (t.team_handicap ?? 0) - lowest);
26	
27	  const skins: Record<string, number> = {};
28	  for (const t of active) skins[t.id] = 0;
29	
30	  let carry = 1;
31	  let decided = 0;
32	  let pending = 0;
33	  const sorted = [...holes].sort((a, b) => a.hole_number - b.hole_number);
34	  for (const h of sorted) {
35	    const entries: { team_id: string; score: number }[] = [];
36	    let allScored = true;
37	    for (const t of active) {
38	      const gross = scoresByTeam[t.id]?.[h.hole_number];
39	      if (gross == null) { allScored = false; break; }
40	      const score = opts.net ? gross - strokesReceivedOnHole(h.handicap_index, adjOf(t)) : gross;
41	      entries.push({ team_id: t.id, score });
42	    }
43	    if (!allScored) { pending++; continue; }
44	    decided++;
45	    const min = Math.min(...entries.map((e) => e.score));
46	    const winners = entries.filter((e) => e.score === min);
47	    if (winners.length === 1) {
48	      skins[winners[0].team_id] += carry;
49	      carry = 1;
50	    } else if (opts.carryover) {
51	      carry += 1;
52	    }
53	  }
54	
55	  const rows = active.map((t) => ({ team_id: t.id, skins: skins[t.id] })).sort((a, b) => b.skins - a.skins);
56	  return { rows, decided, pending };
57	}
